async function seedCountries() {
  console.log("Seeding Countries...");
  const countries = [
    { name: "India", code: "IN", phoneCode: "+91", currencyCode: "INR", currencySymbol: "\u20B9", flag: "\u{1F1EE}\u{1F1F3}", isDefault: true, allowRegistration: true, taxRate: 18 },
    { name: "United States", code: "US", phoneCode: "+1", currencyCode: "USD", currencySymbol: "$", flag: "\u{1F1FA}\u{1F1F8}", isDefault: false, allowRegistration: true, taxRate: 0 },
    { name: "United Kingdom", code: "GB", phoneCode: "+44", currencyCode: "GBP", currencySymbol: "\xA3", flag: "\u{1F1EC}\u{1F1E7}", isDefault: false, allowRegistration: true, taxRate: 20 },
    { name: "United Arab Emirates", code: "AE", phoneCode: "+971", currencyCode: "AED", currencySymbol: "AED", flag: "\u{1F1E6}\u{1F1EA}", isDefault: false, allowRegistration: true, taxRate: 5 },
    { name: "Singapore", code: "SG", phoneCode: "+65", currencyCode: "SGD", currencySymbol: "S$", flag: "\u{1F1F8}\u{1F1EC}", isDefault: false, allowRegistration: true, taxRate: 8 },
    { name: "Canada", code: "CA", phoneCode: "+1", currencyCode: "CAD", currencySymbol: "C$", flag: "\u{1F1E8}\u{1F1E6}", isDefault: false, allowRegistration: true, taxRate: 13 },
    { name: "Australia", code: "AU", phoneCode: "+61", currencyCode: "AUD", currencySymbol: "A$", flag: "\u{1F1E6}\u{1F1FA}", isDefault: false, allowRegistration: true, taxRate: 10 },
    { name: "Germany", code: "DE", phoneCode: "+49", currencyCode: "EUR", currencySymbol: "\u20AC", flag: "\u{1F1E9}\u{1F1EA}", isDefault: false, allowRegistration: true, taxRate: 19 },
    { name: "France", code: "FR", phoneCode: "+33", currencyCode: "EUR", currencySymbol: "\u20AC", flag: "\u{1F1EB}\u{1F1F7}", isDefault: false, allowRegistration: true, taxRate: 20 }
  ];
  for (const c of countries) {
    await prisma.country.upsert({
      where: { name: c.name },
      create: c,
      update: c
    });
  }
  console.log(`\u2713 Seeded ${countries.length} Countries.`);
}
async function seedCurrencies() {
  console.log("Seeding Currencies...");
  const currencies = [
    { name: "Indian Rupee", code: "INR", symbol: "\u20B9", isBase: true, isDefault: true, exchangeRate: 1, decimalPlaces: 2 },
    { name: "US Dollar", code: "USD", symbol: "$", isBase: false, isDefault: false, exchangeRate: 83.5, decimalPlaces: 2 },
    { name: "Euro", code: "EUR", symbol: "\u20AC", isBase: false, isDefault: false, exchangeRate: 90.2, decimalPlaces: 2 },
    { name: "British Pound", code: "GBP", symbol: "\xA3", isBase: false, isDefault: false, exchangeRate: 105.4, decimalPlaces: 2 },
    { name: "UAE Dirham", code: "AED", symbol: "AED", isBase: false, isDefault: false, exchangeRate: 22.7, decimalPlaces: 2 },
    { name: "Singapore Dollar", code: "SGD", symbol: "S$", isBase: false, isDefault: false, exchangeRate: 61.8, decimalPlaces: 2 }
  ];
  for (const curr of currencies) {
    await prisma.currency.upsert({
      where: { code: curr.code },
      create: curr,
      update: curr
    });
  }
  console.log(`\u2713 Seeded ${currencies.length} Currencies.`);
}
async function seedLanguages() {
  console.log("Seeding Languages...");
  const languages = [
    "English",
    "Hindi",
    "Bengali",
    "Tamil",
    "Telugu",
    "Marathi",
    "Gujarati",
    "Kannada",
    "Malayalam",
    "Punjabi",
    "Spanish",
    "French",
    "German",
    "Arabic"
  ];
  for (const name of languages) {
    await prisma.language.upsert({
      where: { name },
      create: { name, status: "active" },
      update: { status: "active" }
    });
  }
  console.log(`\u2713 Seeded ${languages.length} Languages.`);
}
